/// Device-scoped imported-texture residency shared by Editor preview renderers.
#[derive(Clone, Default)]
pub struct SharedPreviewGpuTextureCache {
    inner: crate::render_backend::SharedDecodedTextureCache,
}

impl SharedPreviewGpuTextureCache {
    /// Releases resident imported textures after current GPU users drop them.
    pub fn clear(&self) {
        self.inner.clear();
    }
}

/// Renderer that draws a runtime world into caller-owned texture views.
pub struct PreviewRenderer {
    renderer: WorldRenderer,
}

impl PreviewRenderer {
    /// Creates an offscreen preview renderer for the requested color format.
    pub async fn new(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        color_format: wgpu::TextureFormat,
    ) -> Result<Self, PreviewRendererError> {
        Self::new_with_shared_textures(
            device,
            queue,
            color_format,
            SharedPreviewGpuTextureCache::default(),
        )
        .await
    }

    /// Creates a preview renderer backed by shared device-local imported textures.
    #[doc(hidden)]
    pub async fn new_with_shared_textures(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        color_format: wgpu::TextureFormat,
        texture_cache: SharedPreviewGpuTextureCache,
    ) -> Result<Self, PreviewRendererError> {
        let renderer = WorldRenderer::new_with_texture_cache(
            device,
            queue,
            color_format,
            texture_cache.inner,
        )
        .await
        .map_err(|source| PreviewRendererError::RenderState {
            message: source.to_string(),
        })?;
        Ok(Self { renderer })
    }
